-- 87 Button Prompts: a tutorial card that names the buttons in the
-- player's hand. Every icon is a sprite_resolver labelled with the glyph id
-- Input.get_prompt returns for its action - "keyboard/space", "xbox/a",
-- "playstation/cross", "switch/b" - so touching another device swaps them
-- all. The moves ask the actions themselves: a tap, a hold (tiers at 0.5,
-- 1 and 1.5 s, the strike on release) and a double tap; the script keeps
-- no timers of its own. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/87-button-prompts.scene"
local FLOOR = -240.0
local HOME = -380
local FAMILIES = { "keyboard", "xbox", "playstation", "switch" }
local FAMILY_NAMES = { xbox = "an Xbox pad", playstation = "a PlayStation pad", switch = "a Switch pad",
    generic = "a pad" }
local INK = { 0.033, 0.013, 0.006 }
local DONE = { 0.020, 0.171, 0.013 }
local TIERS = { 0.5, 1.0, 1.5 }

local captions = true
local e = {}
local shown = {}
local y, vy = 0, 0
local dash = 0
local level = 0
local blast = nil
local wobble = 0
local flash = 0
local t = 0

local function show(icon, glyph)
    if shown[icon] ~= glyph then
        shown[icon] = glyph
        Sprite.set_label(icon, glyph)
    end
end

local function done(name)
    Text.set_color(e[name .. "Name"], DONE[1], DONE[2], DONE[3], 1)
end

function init(entity)
    Input.set_bindings("bp_jump", { "Space", "Pad0_A" })
    Input.set_bindings("bp_charge", { "F", "Pad0_X" })
    Input.set_bindings("bp_dash", { "D", "Pad0_RightBumper" })
    for _, n in ipairs({ "Monk", "Ghost", "Dummy", "Glow", "Blast", "Burst", "ChargeFill", "JumpIcon", "ChargeIcon",
        "DashIcon", "JumpName", "ChargeName", "DashName", "Status", "Strip0", "Strip1", "Strip2",
        "Strip3" }) do
        e[n] = Entity.find_by_name(n)
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    t = t + dt

    -- The card follows the device in hand.
    show(e.JumpIcon, Input.get_prompt("bp_jump").glyph)
    show(e.ChargeIcon, Input.get_prompt("bp_charge").glyph)
    show(e.DashIcon, Input.get_prompt("bp_dash").glyph)
    for i, fam in ipairs(FAMILIES) do
        show(e["Strip" .. (i - 1)], Input.get_prompt("bp_jump", fam).glyph)
    end
    local pad = Input.get_last_gamepad()
    if Input.get_last_device() == "gamepad" and pad >= 0 then
        local kind = Input.get_gamepad_type(pad)
        UI.set_text(e.Status, "in hand: " .. (FAMILY_NAMES[kind] or "a pad") .. " - " .. Input.get_gamepad_name(pad))
    else
        local dev = Input.get_last_device()
        UI.set_text(e.Status, "in hand: " .. (dev == "none" and "the keyboard (touch anything)" or ("the " .. dev)))
    end

    -- Jump: a tap.
    if Input.is_action_tapped("bp_jump") and y <= 0 then
        vy = 620
        done("Jump")
    end
    vy = vy - 1900 * dt
    y = math.max(0, y + vy * dt)
    if y <= 0 then vy = 0 end

    -- Charge: held, it glows and climbs through the tiers; let go to strike.
    local held = Input.get_hold_time("bp_charge")
    if held > 0 then level = held end
    for _, s in ipairs(TIERS) do
        -- True on the one frame the press reaches each tier.
        if Input.is_action_held("bp_charge", s) then flash = 1 end
    end
    flash = math.max(0, flash - dt * 4)
    local fill = math.min(level, 1.5) / 1.5
    Transform.set_scale(e.ChargeFill, math.max(fill, 0.001), 1)
    local glow = held > 0 and math.min(1, 0.25 + 0.75 * fill + 0.5 * flash) or 0
    local k = (0.25 + 0.75 * fill) * (1 + 0.08 * math.sin(t * 18) + 0.35 * flash)
    Transform.set_scale(e.Glow, k, k)
    Sprite.set_color(e.Glow, 1.0, 0.62, 0.22, glow)
    if Input.is_action_just_released("bp_charge") then
        local tier = 0
        for i, s in ipairs(TIERS) do if level >= s then tier = i end end
        if tier > 0 and blast == nil then
            blast = { x = HOME + 50 + dash, tier = tier }
            done("Charge")
        end
        level = 0
    end

    -- Dash: a double tap - forward, and drift home.
    if Input.is_action_double_tapped("bp_dash") then
        dash = 240
        Sprite.set_color(e.Ghost, 1.0, 0.75, 0.4, 0.55)
        done("Dash")
    end
    dash = dash * math.exp(-4.0 * dt)
    local gx = HOME + dash * 0.6
    Transform.set_position(e.Ghost, gx, FLOOR + y)
    local gr, gg, gb, ga = Sprite.get_color(e.Ghost)
    Sprite.set_color(e.Ghost, 1.0, 0.75, 0.4, math.max(0, (ga or 0) - dt * 1.5))

    local mx = HOME + dash
    Transform.set_position(e.Monk, mx, FLOOR + y)
    Transform.set_position(e.Glow, mx + 55, FLOOR + 92 + y)

    -- The strike flies to the dummy; tier sets its size.
    if blast then
        blast.x = blast.x + 1100 * dt
        local s = (40 + 40 * blast.tier) / 60
        Transform.set_position(e.Blast, blast.x, FLOOR + 100)
        Transform.set_scale(e.Blast, s, s)
        Sprite.set_color(e.Blast, 1.0, 0.75, 0.35, 1)
        if blast.x >= 480 then
            wobble = 0.12 + 0.1 * blast.tier
            Particles.emit_burst(e.Burst, 20 * blast.tier)
            blast = nil
            Sprite.set_color(e.Blast, 1.0, 0.75, 0.35, 0)
        end
    end
    wobble = wobble * math.exp(-2.5 * dt)
    Transform.set_rotation(e.Dummy, -wobble * math.sin(t * 22))
end
